// This module is consumed after the v10 runtime is generated by the Pages build.
import {LEVELS as BASE_LEVELS,WORLDS} from './levels-v10-runtime.js';
import {PROBLEM_BANK} from './problem-bank-v11-fix.js';
import {constraintText} from './constraints-v11.js';
export {WORLDS};
export const LEVELS=structuredClone(BASE_LEVELS);
let ID=70000;
const W=(x,y,text)=>({id:`v11w${++ID}`,kind:'word',x,y,text});
const O=(x,y,noun,extra={})=>({id:`v11o${++ID}`,kind:'object',x,y,noun,...extra});
const F=(x,y,floorType,extra={})=>({id:`v11f${++ID}`,kind:'floor',x,y,floorType,...extra});

function makeLock(spec,base){
  const slots=spec.data.slots;
  const socketXs=slots.length===4?[3,5,7,9]:[4,6,8];
  const entities=[W(0,0,'ZERO'),W(1,0,'IS'),W(2,0,'YOU'),W(0,1,'WALL'),W(1,1,'IS'),W(2,1,'STOP'),O(1,7,'ZERO')];
  slots.forEach((slot,i)=>entities.push(F(socketXs[i],2,'SOCKET',{socket:slot,label:slot})));
  // Broken barrier prevents every candidate from being a straight vertical shove.
  [[4,4],[5,4],[8,4],[9,4]].forEach(([x,y])=>entities.push(O(x,y,'WALL')));
  // Stagger rows so candidates never begin as accidental push-chains.
  const spots=[[2,5],[4,5],[6,5],[8,5],[10,5],[3,6],[5,6],[7,6],[9,6],[11,6]];
  spec.data.candidates.forEach((t,i)=>entities.push(W(spots[i][0],spots[i][1],t)));
  return {
    ...base,
    world:spec.world,title:spec.title,concept:spec.concept,hint:spec.hint,
    reasoningSteps:spec.reasoning,sourceBasis:spec.sourceBasis,entities,
    goal:{type:'constraintSockets',slots:[...slots],constraints:structuredClone(spec.data.constraints),distinct:spec.data.distinct!==false},
    constraintDisplay:spec.data.constraints.map(constraintText),
    solution:structuredClone(spec.data.solution),
    challengePack:11,noStraightPush:true,lockPuzzle:true,
  };
}

PROBLEM_BANK.forEach((spec,i)=>{if(spec.kind==='lock')LEVELS[i]=makeLock(spec,LEVELS[i]);});
export const LEVEL_BY_ID=Object.fromEntries(LEVELS.map(l=>[l.id,l]));
